import sys, io, re
from collections import Counter
sys.stdout = io.TextIOWrapper\(sys.stdout.buffer, encoding='utf-8'\)

with open\('Sophia中文识字进阶表_2000字.md', 'r', encoding='utf-8'\) as f:
    content = f.read\(\)

# Count stage 1 sub-parts
part_chars = {}
current_part = None
current_stage = None

for line in content.split\('\\n'\):
    stripped = line.strip\(\)
    if stripped.startswith\('## '\) and '阶段' in stripped:
        current_stage = stripped
        current_part = None
    elif stripped.startswith\('### '\) and current_stage and '第一阶段' in current_stage:
        current_part = stripped.replace\('### ', ''\)
        part_chars[current_part] = []
    elif stripped and not stripped.startswith\('#'\) and not stripped.startswith\('>'\) and not stripped.startswith\('---'\) and current_part:
        chars = re.findall\(r'[\\u4e00-\\u9fff]', stripped\)
        if chars:
            part_chars[current_part].extend\(chars\)

print\('=== 第一阶段 4部分验证 ==='\)
s1_total = 0
for name, chars in part_chars.items\(\):
    print\(f'{name}: {len\(chars\)}字'\)
    s1_total += len\(chars\)
print\(f'第一阶段合计: {s1_total}字'\)

# Count all stages
print\('\\n=== 全文档验证 ==='\)
stage_chars = {}
current_stage = None
for line in content.split\('\\n'\):
    stripped = line.strip\(\)
    if stripped.startswith\('## '\) and '阶段' in stripped:
        current_stage = stripped
        stage_chars[current_stage] = []
    elif stripped and not stripped.startswith\('#'\) and not stripped.startswith\('>'\) and not stripped.startswith\('---'\) and current_stage:
        chars = re.findall\(r'[\\u4e00-\\u9fff]', stripped\)
        if chars:
            stage_chars[current_stage].extend\(chars\)

all_chars = []
for stage, chars in stage_chars.items\(\):
    print\(f'{stage}: {len\(chars\)}字'\)
    all_chars.extend\(chars\)

print\(f'\\n总计: {len\(all_chars\)}字'\)
print\(f'去重: {len\(set\(all_chars\)\)}字'\)

counts = Counter\(all_chars\)
dups = {c: n for c, n in counts.items\(\) if n > 1}
if dups:
    print\(f'重复: {len\(dups\)}个'\)
else:
    print\('零重复!'\)

if len\(all_chars\) == 2000 and len\(set\(all_chars\)\) == 2000:
    print\('\\n✓ 完美! 2000字无重复，第一阶段4x300!'\)
